import { NextFunction, Request, Response, Router } from "express";
import { CreateTaskInput, InvalidInputError, TaskService } from "../application/task-service";
import { TaskAlreadyDoneError } from "../domain/task";

type Body = Record<string, unknown>;

export class TaskController {
  public constructor(private readonly service: TaskService) {}

  public register(router: Router): void {
    router.post("/users", this.createUser);
    router.post("/projects", this.createProject);
    router.post("/projects/:projectId/tasks", this.createTask);
    router.get("/projects/:projectId/tasks", this.listTasks);
    router.patch("/tasks/:taskId/done", this.markDone);
  }

  private createUser = (request: Request, response: Response, next: NextFunction): void => {
    try {
      response.status(201).json(this.service.createUser({ name: this.requiredText(this.body(request).name, "name") }));
    } catch (error) { next(error); }
  };

  private createProject = (request: Request, response: Response, next: NextFunction): void => {
    try {
      response.status(201).json(this.service.createProject({ name: this.requiredText(this.body(request).name, "name") }));
    } catch (error) { next(error); }
  };

  private createTask = (request: Request, response: Response, next: NextFunction): void => {
    try {
      const body = this.body(request);
      const input: CreateTaskInput = {
        title: this.requiredText(body.title, "title"),
        description: this.requiredText(body.description, "description"),
        dueDate: this.optionalText(body.dueDate, "dueDate"),
        status: this.optionalText(body.status, "status") as CreateTaskInput["status"],
        assigneeId: this.optionalText(body.assigneeId, "assigneeId"),
      };
      response.status(201).json(this.service.createTask(this.routeParam(request, "projectId"), input));
    } catch (error) { next(error); }
  };

  private listTasks = (request: Request, response: Response, next: NextFunction): void => {
    try {
      const status = this.optionalText(request.query.status, "status") as CreateTaskInput["status"];
      const assigneeId = this.optionalText(request.query.assigneeId, "assigneeId");
      response.json(this.service.listProjectTasks(this.routeParam(request, "projectId"), { status, assigneeId }));
    } catch (error) { next(error); }
  };

  private markDone = (request: Request, response: Response, next: NextFunction): void => {
    try {
      response.json(this.service.markTaskDone(this.routeParam(request, "taskId")));
    } catch (error) { next(error); }
  };

  private body(request: Request): Body {
    if (typeof request.body !== "object" || request.body === null || Array.isArray(request.body)) {
      throw new InvalidInputError("A JSON object body is required");
    }
    return request.body as Body;
  }

  private requiredText(value: unknown, field: string): string {
    if (typeof value !== "string" || value.trim() === "") throw new InvalidInputError(`${field} is required`);
    return value;
  }

  private optionalText(value: unknown, field: string): string | undefined {
    if (value === undefined) return undefined;
    if (typeof value !== "string") throw new InvalidInputError(`${field} must be a string`);
    return value;
  }

  private routeParam(request: Request, name: string): string {
    const value = request.params[name];
    if (typeof value !== "string" || value === "") throw new InvalidInputError(`${name} is required`);
    return value;
  }
}

export function errorHandler(error: unknown, _request: Request, response: Response, _next: NextFunction): void {
  if (error instanceof InvalidInputError) {
    response.status(400).json({ error: error.message });
    return;
  }
  if (error instanceof TaskAlreadyDoneError) {
    response.status(409).json({ error: error.message });
    return;
  }
  if (error instanceof Error && error.name === "ResourceNotFoundError") {
    response.status(404).json({ error: error.message });
    return;
  }
  response.status(500).json({ error: "Internal server error" });
}

